import React, { useState } from "react";

export default function welcometoTouristRegistration() {
  const [formData, setFormData] = useState({
    name: "",
    country: "",
    phone: "",
    idProof: "",
  });
  const [registered, setRegistered] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!formData.name || !formData.country || !formData.phone || !formData.idProof) {
      alert("Please fill all fields!");
      return;
    }

    // later we’ll send data to backend here
    setRegistered(true);
  };

  return (
    <div
      style={{
        height: "100vh",
        background: "linear-gradient(135deg, #ff9a3c, #ff6f00)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      {!registered ? (
        <form
          onSubmit={handleSubmit}
          style={{
            backgroundColor: "rgba(255,255,255,0.95)",
            padding: "40px",
            borderRadius: "20px",
            boxShadow: "0px 10px 30px rgba(0,0,0,0.2)",
            width: "350px",
            textAlign: "center",
          }}
        >
          <h2 style={{ color: "#ff6f00", marginBottom: "20px" }}>
            🧳 Tourist Registration
          </h2>

          <input
            type="text"
            name="name"
            placeholder="Full Name"
            value={formData.name}
            onChange={handleChange}
            style={inputStyle}
          />
          <input
            type="text"
            name="country"
            placeholder="Country of Origin"
            value={formData.country}
            onChange={handleChange}
            style={inputStyle}
          />
          <input
            type="tel"
            name="phone"
            placeholder="Phone Number"
            value={formData.phone}
            onChange={handleChange}
            style={inputStyle}
          />
          <input
            type="text"
            name="idProof"
            placeholder="Aadhaar / Passport / ID Proof"
            value={formData.idProof}
            onChange={handleChange}
            style={inputStyle}
          />

          <button
            type="submit"
            style={{
              width: "100%",
              padding: "10px",
              backgroundColor: "#ff6f00",
              color: "white",
              border: "none",
              borderRadius: "10px",
              cursor: "pointer",
              marginTop: "15px",
              fontWeight: "bold",
              fontSize: "16px",
            }}
          >
            Register
          </button>
        </form>
      ) : (
        <div
          style={{
            backgroundColor: "rgba(255,255,255,0.95)",
            padding: "40px",
            borderRadius: "20px",
            boxShadow: "0px 10px 30px rgba(0,0,0,0.2)",
            textAlign: "center",
          }}
        >
          <h2 style={{ color: "#ff6f00" }}>Welcome, {formData.name}! 🎉</h2>
          <p style={{ marginTop: "10px" }}>
            Your registration is successful.<br />
            <strong>Your Block ID</strong> will be generated next.
          </p>
        </div>
      )}
    </div>
  );
}

const inputStyle = {
  width: "100%",
  padding: "10px",
  marginBottom: "10px",
  borderRadius: "10px",
  border: "1px solid #ccc",
};
